=Aşağıdaki metinden Türkçe 5 adet çoktan seçmeli soru üret. Sadece şu JSON şemasını döndür:
{"questions":[{"question":"...","options":["A","B","C","D"],"correct_answer":"doğru şık metni"}]}

Metin: {{ $json.body.text }}

parameters.jsCode:
const rawOutput = $input.first().json.content || $input.first().json.text || $input.first().json.response || '';

let parsed;
try {
  const cleaned = rawOutput.replace(/```json/gi, '').replace(/```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  throw new Error('JSON_PARSE_ERROR: Model gecerli JSON uretmedi. Ham cikti: ' + rawOutput.slice(0, 150));
}

if (!parsed || !Array.isArray(parsed.questions)) {
  throw new Error('SCHEMA_ERROR: questions dizisi bulunamadi.');
}

if (parsed.questions.length < 5) {
  throw new Error(`VALIDATION_ERROR: En az 5 soru gerekli, uretilen: ${parsed.questions.length}`);
}

const stripPrefix = (str) => String(str).replace(/^[A-Da-d][\)\.\-\:]\s*/, '').trim().toLowerCase();

const validatedQuestions = parsed.questions.map((q, index) => {
  if (!q.question || typeof q.question !== 'string') {
    throw new Error(`VALIDATION_ERROR: Soru ${index + 1} metni gecersiz.`);
  }
  if (!Array.isArray(q.options) || q.options.length !== 4) {
    throw new Error(`VALIDATION_ERROR: Soru ${index + 1} icin tam 4 secenek gerekli.`);
  }

  const options = q.options.map(opt => String(opt).trim());
  const rawAnswer = String(q.correct_answer || '').trim();
  let matchedOption = null;

  // 1. Birebir eşleşme kontrolü
  if (options.includes(rawAnswer)) {
    matchedOption = rawAnswer;
  }
  // 2. Harf prefixi temizlenmiş metin eşleşmesi (Örn: "A) LIFO" vs "LIFO")
  else {
    const cleanAns = stripPrefix(rawAnswer);
    matchedOption = options.find(opt => stripPrefix(opt) === cleanAns);
  }
  // 3. Sadece harf döndürdüyse (Örn: "A", "B", "C", "D") indeks üzerinden eşleştir
  if (!matchedOption && /^[A-Da-d][\)\.]?$/.test(rawAnswer)) {
    const letterIndex = rawAnswer.toUpperCase().charCodeAt(0) - 65;
    if (letterIndex >= 0 && letterIndex < 4) {
      matchedOption = options[letterIndex];
    }
  }

  if (!matchedOption) {
    throw new Error(`VALIDATION_ERROR: Soru ${index + 1} correct_answer (${rawAnswer}) secenekler icinde yer almiyor.`);
  }

  return {
    id: index + 1,
    question: q.question.trim(),
    options: options,
    correct_answer: matchedOption
  };
});

const webhookBody = $('Webhook Generate Quiz').first().json.body || {};

return [
  {
    json: {
      source_id: webhookBody.source_id || null,
      title: webhookBody.title || 'Ders Testi',
      questions: validatedQuestions,
      created_at: new Date().toISOString()
    }
  }
];

const validatedData = $('Validate Quiz Schema').first().json;
const mongoResult = $input.first().json;

const clientQuestions = validatedData.questions.map(q => ({
  id: q.id,
  question: q.question,
  options: q.options
}));

return [
  {
    json: {
      quiz_id: mongoResult._id || mongoResult.insertedId || null,
      title: validatedData.title,
      total_questions: clientQuestions.length,
      questions: clientQuestions
    }
  }
];
